description:
Use **static storage** so that these functions can safely hand out pointers and references that stay valid:

```cpp
int nextTicket();
const char* monthName(int month);
std::string& lastError();
int* sharedCounter();
```

- **nextTicket** returns 1 the first time it is called, then 2, 3 and so on. Keep the count in a `static` local, not a global.
- **monthName** returns `"January"` for 1 up to `"December"` for 12, and `"?"` for anything else. Returning string literals is safe: they live for the whole program.
- **lastError** returns a reference to one `std::string` that lives for the whole program, so that `lastError() = "disk full";` is seen by every later call.
- **sharedCounter** returns a pointer to one `int`, the same address on every call, starting at 0.

starter.solution.cpp:
#include <string>

int nextTicket() { return 0; }
const char* monthName(int month) { return ""; }
std::string& lastError() { std::string* fresh{ new std::string }; return *fresh; }
int* sharedCounter() { return new int{ 0 }; }

solution.solution.cpp:
#include <string>

int nextTicket()
{
    static int next{ 1 };
    return next++;
}

const char* monthName(int month)
{
    static const char* const names[]{ "January", "February", "March", "April", "May", "June",
                                      "July", "August", "September", "October", "November", "December" };
    if (month < 1 || month > 12) return "?";
    return names[month - 1];
}

std::string& lastError()
{
    static std::string message;
    return message;
}

int* sharedCounter()
{
    static int counter{ 0 };
    return &counter;
}

unitTests:
#include <cstring>
TEST("tickets count up") {
    const int first{ nextTicket() };
    CHECK_EQ(first, 1);
    CHECK_EQ(nextTicket(), 2);
    CHECK_EQ(nextTicket(), 3);
}
TEST("month names") {
    CHECK_EQ(std::string(monthName(1)), std::string("January"));
    CHECK_EQ(std::string(monthName(12)), std::string("December"));
    CHECK_EQ(std::string(monthName(13)), std::string("?"));
    CHECK_EQ(std::string(monthName(0)), std::string("?"));
    CHECK(monthName(5) == monthName(5));
}
TEST("one error string for everyone") {
    lastError() = "disk full";
    CHECK_EQ(lastError(), std::string("disk full"));
    CHECK(&lastError() == &lastError());
}
TEST("one shared counter") {
    int* a{ sharedCounter() };
    int* b{ sharedCounter() };
    CHECK(a == b);
    CHECK_EQ(*a, 0);
    *a += 5;
    CHECK_EQ(*sharedCounter(), 5);
}

